--
-- Name: trips; Type: TABLE; Schema: public; Owner: osmuser; Tablespace: 
--

CREATE TABLE public.trips (
    file_name text,
    lon text,
    lat text,
    tms text,
    devid text,
    roads text,
    "time" text,
    frac text,
    route text,
    route_heading text,
    route_geom text
);


ALTER TABLE public.trips OWNER TO osmuser;

--
-- Name: COLUMN trips.file_name; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.file_name IS '每天的jld文件名';


--
-- Name: COLUMN trips.lon; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.lon IS '出租车行驶中定时抓取的经度';


--
-- Name: COLUMN trips.lat; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.lat IS '出租车行驶中定时抓取的纬度';


--
-- Name: COLUMN trips.tms; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.tms IS '出租车行驶中定时抓取的时间';


--
-- Name: COLUMN trips.devid; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.devid IS '出租车ID';


--
-- Name: COLUMN trips.roads; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.roads IS '道路id，bfmap_ways中的gid';


--
-- Name: COLUMN trips."time"; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips."time" IS 'timestamp，roads中每道路点的时间';


--
-- Name: COLUMN trips.frac; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.frac IS '行驶过程的距离比例，可根据bfmap_ways中gid中的length计算出行驶距离';


--
-- Name: COLUMN trips.route; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.route IS '行驶过程的道路id，bfmap_ways中的gid';


--
-- Name: COLUMN trips.route_heading; Type: COMMENT; Schema: public; Owner: osmuser
--

COMMENT ON COLUMN public.trips.route_heading IS '行驶过程在道路的正反';



